CREATE TABLE public.payout_pilot_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), restaurant_id uuid NOT NULL REFERENCES public.restaurants(id), uber_store_id text NOT NULL CHECK (uber_store_id IN ('a7d5bd5a-0225-50a0-8ffb-78162ae651e7','c3eee44c-0a67-5bda-9020-df3fdf328371','37b27fc0-bb7e-5c2e-abd0-48dd5471d2c4')), start_date date NOT NULL, end_date date NOT NULL, workflow_id text UNIQUE, status text NOT NULL DEFAULT 'reserved', sections jsonb, refusal_status integer, created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, UNIQUE(uber_store_id,start_date,end_date), CHECK(start_date >= DATE '2026-06-01' AND end_date <= DATE '2026-11-15' AND end_date-start_date BETWEEN 0 AND 29)); GRANT ALL ON public.payout_pilot_reports TO service_role; REVOKE ALL ON public.payout_pilot_reports FROM anon,authenticated; ALTER TABLE public.payout_pilot_reports ENABLE ROW LEVEL SECURITY;